import React, { useState } from 'react';
import ColorPicker from './ColorPicker';
import StarRating from './StarRating';
import './ProductSlider.css';

const ProductSlider = ({ products }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [selectedColor, setSelectedColor] = useState('yellow');
  const [imageLoaded, setImageLoaded] = useState(false);

  const currentProduct = products[currentIndex];
  
  if (!currentProduct) return null;

  const handleColorChange = (color) => {
    setSelectedColor(color);
    setImageLoaded(false);
  };

  const handleImageLoad = () => {
    setImageLoaded(true);
  };

  const nextProduct = () => {
    setCurrentIndex((prev) => (prev + 1) % products.length);
    setImageLoaded(false);
  };

  const prevProduct = () => {
    setCurrentIndex((prev) => (prev - 1 + products.length) % products.length);
    setImageLoaded(false);
  };

  const colors = currentProduct.images ? Object.keys(currentProduct.images) : [];
  const currentImage = currentProduct.images ? currentProduct.images[selectedColor] : '';

  return (
    <div className="product-slider">
      <div className="product-slider-container">
        <div className="product-slider-content">
          <div className="product-image-section">
            <div className={`product-main-image ${imageLoaded ? 'loaded' : 'loading'}`}>
              {currentImage ? (
                <img 
                  src={currentImage} 
                  alt={currentProduct.name}
                  onLoad={handleImageLoad}
                  loading="lazy"
                />
              ) : (
                <div className="no-image-placeholder">
                  <span>No Image Available</span>
                </div>
              )}
              {!imageLoaded && currentImage && (
                <div className="image-loading-overlay">
                  <div className="loading-spinner"></div>
                </div>
              )}
            </div>
          </div>
          
          <div className="product-details-section">
            <h2 className="product-title">Product Title</h2>
            <div className="product-price-display">
              ${currentProduct.price ? currentProduct.price.toFixed(2) : '101.00'} USD
            </div>
            
            <div className="product-color-selection">
              {colors.length > 0 && (
                <ColorPicker 
                  colors={colors}
                  selectedColor={selectedColor}
                  onColorChange={handleColorChange}
                />
              )}
            </div>
            
            <div className="product-rating-section">
              <StarRating rating={currentProduct.rating || 4.5} />
              <span className="rating-display">{(currentProduct.rating || 4.5).toFixed(1)}/5</span>
            </div>
          </div>
        </div>
        
        <button 
          className="slider-nav-btn slider-nav-next"
          onClick={nextProduct}
          aria-label="Next product"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
            <path d="M9 18L15 12L9 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        </button>
        
        <button 
          className="slider-nav-btn slider-nav-prev"
          onClick={prevProduct}
          aria-label="Previous product"
        >
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
            <path d="M15 18L9 12L15 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        </button>
      </div>
      
      <div className="slider-indicators">
        {products.map((_, index) => (
          <button
            key={index}
            className={`slider-indicator ${index === currentIndex ? 'active' : ''}`}
            onClick={() => {
              setCurrentIndex(index);
              setImageLoaded(false);
            }}
            aria-label={`Go to product ${index + 1}`}
          />
        ))}
      </div>
    </div>
  );
};

export default ProductSlider;
